package main

import (
	"encoding/json"
	"fmt"
	"net/http"
	"time"
)

type TokenChunk struct {
	Token string `json:"token"`
	Index int    `json:"index"`
}

func chatStreamHandler(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "text/event-stream")
	w.Header().Set("Cache-Control", "no-cache")
	w.Header().Set("Connection", "keep-alive")
	w.Header().Set("X-Accel-Buffering", "no")

	rc := http.NewResponseController(w)

	// Имитация ответа языковой модели
	responseTokens := []string{
		"Golang", " —", " это", " компилируемый,", " многопоточный",
		" язык", " программирования,", " разработанный", " Google.",
	}

	for i, token := range responseTokens {
		select {
		case <-r.Context().Done():
			// Пользователь отменил генерацию
			fmt.Println("Generation aborted by user.")
			return
		default:
		}

		payload, _ := json.Marshal(TokenChunk{
			Token: token,
			Index: i,
		})

		// Отправляем токен
		if _, err := fmt.Fprintf(w, "data: %s\n\n", payload); err != nil {
			return
		}
		if err := rc.Flush(); err != nil {
			return
		}

		// Имитация скорости генерации LLM (50 мс на токен)
		time.Sleep(50 * time.Millisecond)
	}

	// Финальный маркер завершения по стандарту OpenAI
	_, _ = fmt.Fprintf(w, "data: [DONE]\n\n")
	_ = rc.Flush()
}

func main() {
	http.HandleFunc("/v1/chat/completions", chatStreamHandler)
	fmt.Println("LLM Streaming API server running on :8080/v1/chat/completions")
	_ = http.ListenAndServe(":8080", nil)
}

// JavaScript клиент на базе fetch и ReadableStream (для поддержки POST с телом)
async function streamChat(prompt) {
    const response = await fetch('/v1/chat/completions', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ prompt: prompt })
    });

    const reader = response.body.getReader();
    const decoder = new TextDecoder();
    let accumulatedText = "";

    while (true) {
        const { value, done } = await reader.read();
        if (done) break;

        const chunk = decoder.decode(value);
        const lines = chunk.split('\n');

        for (const line of lines) {
            if (line.startsWith('data: ')) {
                const data = line.slice(6).trim();
                if (data === '[DONE]') {
                    console.log("Generation complete!");
                    return;
                }
                const parsed = JSON.parse(data);
                accumulatedText += parsed.token;
                document.getElementById('output').innerText = accumulatedText;
            }
        }
    }
}

package main

import (
	"encoding/json"
	"fmt"
	"net/http"
	"strings"
	"sync"
	"time"
)

type MarketQuote struct {
	Symbol string  `json:"symbol"`
	Price  float64 `json:"price"`
}

type FilteredClient struct {
	symbols map[string]struct{}
	ch      chan MarketQuote
}

type FilterBroker struct {
	mu      sync.RWMutex
	clients map[*FilteredClient]struct{}
}

func NewFilterBroker() *FilterBroker {
	return &FilterBroker{
		clients: make(map[*FilteredClient]struct{}),
	}
}

func (b *FilterBroker) Register(symbols []string) *FilteredClient {
	b.mu.Lock()
	defer b.mu.Unlock()

	filter := make(map[string]struct{})
	for _, s := range symbols {
		filter[strings.ToUpper(strings.TrimSpace(s))] = struct{}{}
	}

	client := &FilteredClient{
		symbols: filter,
		ch:      make(chan MarketQuote, 32),
	}
	b.clients[client] = struct{}{}
	return client
}

func (b *FilterBroker) Unregister(client *FilteredClient) {
	b.mu.Lock()
	defer b.mu.Unlock()
	delete(b.clients, client)
	close(client.ch)
}

func (b *FilterBroker) BroadcastQuote(quote MarketQuote) {
	b.mu.RLock()
	defer b.mu.RUnlock()

	for client := range b.clients {
		if _, interested := client.symbols[quote.Symbol]; interested {
			select {
			case client.ch <- quote:
			default:
				// Дроп для медленного клиента
			}
		}
	}
}

func filterStreamHandler(b *FilterBroker) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		symbolsParam := r.URL.Query().Get("symbols")
		if symbolsParam == "" {
			http.Error(w, "symbols query param required (e.g. ?symbols=BTC,ETH)", http.StatusBadRequest)
			return
		}

		symbols := strings.Split(symbolsParam, ",")
		client := b.Register(symbols)
		defer b.Unregister(client)

		w.Header().Set("Content-Type", "text/event-stream")
		w.Header().Set("Cache-Control", "no-cache")
		w.Header().Set("Connection", "keep-alive")

		rc := http.NewResponseController(w)
		fmt.Fprintf(w, ": subscribed to %s\n\n", symbolsParam)
		_ = rc.Flush()

		for {
			select {
			case <-r.Context().Done():
				return
			case quote, ok := <-client.ch:
				if !ok {
					return
				}
				data, _ := json.Marshal(quote)
				if _, err := fmt.Fprintf(w, "event: quote\ndata: %s\n\n", data); err != nil {
					return
				}
				if err := rc.Flush(); err != nil {
					return
				}
			}
		}
	}
}

func main() {
	broker := NewFilterBroker()

	// Генератор котировок
	go func() {
		quotes := []MarketQuote{
			{Symbol: "BTC", Price: 65120.50},
			{Symbol: "ETH", Price: 3450.20},
			{Symbol: "SOL", Price: 145.80},
			{Symbol: "TON", Price: 6.75},
		}
		for {
			for _, q := range quotes {
				q.Price += 0.50
				broker.BroadcastQuote(q)
				time.Sleep(200 * time.Millisecond)
			}
		}
	}()

	http.HandleFunc("/market-stream", filterStreamHandler(broker))
	fmt.Println("Filtered market SSE server listening on :8080/market-stream?symbols=BTC,ETH")
	_ = http.ListenAndServe(":8080", nil)
}

